import org.redisson.api.RLock;
import org.redisson.api.RedissonClient;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import java.util.concurrent.TimeUnit;

@RestController
@RequestMapping("/stock")
public class StockController {
    @Autowired
    private StringRedisTemplate stringRedisTemplate;
    @Autowired
    private RedissonClient redissonClient;
    private static final String LOCK_KEY = "stock_lock_1001";
    private static final String STOCK_KEY = "stock_1001";
    private static final int INIT_STOCK = 1000;
    private static final int LOCK_WAIT_TIME = 100; // 锁等待时间100ms
    private static final int LOCK_LEASE_TIME = 30; // 锁初始过期时间30秒，Redisson自动续期

    @GetMapping("/deduct")
    public Result deduct(@RequestParam Integer deductNum) {
        // 1. 前置参数校验，非法参数直接返回，不占用锁资源
        if (deductNum == null || deductNum < 1 || deductNum > 10) {
            return Result.error(4002, "参数非法");
        }
        RLock lock = redissonClient.getLock(LOCK_KEY);
        try {
            // 2. 尝试获取锁，获取失败直接返回系统繁忙
            if (!lock.tryLock(LOCK_WAIT_TIME, LOCK_LEASE_TIME, TimeUnit.SECONDS)) {
                return Result.error(5000, "系统繁忙，请稍后重试");
            }
            // 3. 获取当前库存，处理数据不存在的边界情况
            Integer currentStock = stringRedisTemplate.opsForValue().get(STOCK_KEY, Integer.class);
            if (currentStock == null) {
                // 初始化库存
                stringRedisTemplate.opsForValue().set(STOCK_KEY, String.valueOf(INIT_STOCK));
                currentStock = INIT_STOCK;
            }
            // 4. 原子扣减库存，decrBy是Redis原子操作，保证扣减过程不被中断
            Long remainStock = stringRedisTemplate.opsForValue().decrBy(STOCK_KEY, deductNum);
            // 5. 扣减后库存不足，回滚操作
            if (remainStock < 0) {
                stringRedisTemplate.opsForValue().incrBy(STOCK_KEY, deductNum);
                return Result.error(4001, "库存不足");
            }
            // 6. 扣减成功，返回剩余库存
            return Result.success(remainStock);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return Result.error(5000, "系统繁忙，请稍后重试");
        } catch (Exception e) {
            // 捕获所有运行时异常，避免服务雪崩
            return Result.error(5000, "系统繁忙，请稍后重试");
        } finally {
            // 7. 仅当当前线程持有锁时才释放，避免误删
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }
}
// 模拟Result工具类，实际项目按需实现
